// Formata o briefing matinal em UMA mensagem escaneavel
const THIAGO_NUMERO = '5511910441709';
const d = items[0].json;

function parse(v){ if (typeof v === 'string') { try { return JSON.parse(v); } catch(e) { return []; } } return v || []; }
const reunioes = parse(d.reunioes_hoje);
const reunioesPend = parse(d.reunioes_pendentes);
const leads = parse(d.leads_novos);
const tarefas = parse(d.tarefas);
const lembretes = parse(d.lembretes_hoje);
const rotina = parse(d.rotina_hoje);
const envios = parse(d.envios_pendentes);

const agora = new Date(Date.now() - (3 * 60 * 60 * 1000));
const diasSem = ['domingo','segunda','terca','quarta','quinta','sexta','sabado'];
const dia = diasSem[agora.getUTCDay()];
const dataFmt = String(agora.getUTCDate()).padStart(2,'0') + '/' + String(agora.getUTCMonth()+1).padStart(2,'0');

let secoes = [];

if (reunioes.length) {
  secoes.push('*Reunioes hoje:*\n' + reunioes.map(r => `  ${r.hora} - ${r.nome}${r.assunto ? ' (' + r.assunto.substring(0,60) + ')' : ''}`).join('\n'));
}
if (reunioesPend.length) {
  secoes.push(`*Aguardando tua aprovacao* (manda "aprovar reuniao ID"):\n` + reunioesPend.map(r => `  #${r.id} ${r.nome}${r.assunto ? ' - ' + r.assunto.substring(0,60) : ''}`).join('\n'));
}
if (leads.length) {
  secoes.push('*Leads novos (24h):*\n' + leads.map(l => `  ${l.nome} - ${l.tipo} em ${l.cidade}`).join('\n'));
}
if (lembretes.length) {
  secoes.push('*Lembretes de hoje:*\n' + lembretes.map(l => `  ${l.hora} - ${l.descricao}`).join('\n'));
}
if (tarefas.length) {
  const atras = tarefas.filter(t => t.atrasada);
  const resto = tarefas.filter(t => !t.atrasada);
  let txt = '*Tarefas pendentes:*';
  if (atras.length) txt += '\n' + atras.map(t => `  #${t.id} ${t.titulo} (ATRASADA${t.prazo ? ' - era ' + t.prazo : ''})`).join('\n');
  if (resto.length) txt += '\n' + resto.slice(0,5).map(t => `  #${t.id} ${t.titulo}${t.prazo ? ' (ate ' + t.prazo + ')' : ''}`).join('\n');
  if (resto.length > 5) txt += `\n  ...e mais ${resto.length - 5}`;
  secoes.push(txt);
}
if (rotina.length) {
  secoes.push('*Rotina de casa:*\n' + rotina.map(t => `  ${t}`).join('\n'));
}
if (envios.length) {
  secoes.push('*Envios aguardando teu OK:*\n' + envios.map(e => `  #${e.id} para ${e.para}`).join('\n'));
}

let texto;
if (!secoes.length) {
  texto = `Bom dia! ${dia.charAt(0).toUpperCase()+dia.slice(1)}, ${dataFmt}. Dia livre por enquanto: sem reunioes, tarefas ou lembretes. Qualquer coisa me chama.`;
} else {
  texto = `Bom dia! Resumo de ${dia}, ${dataFmt}:\n\n` + secoes.join('\n\n');
}

return [{ json: { send_to: THIAGO_NUMERO, send_text: texto } }];
